-- Ulam Roulette dish catalogue, portable Postgres dump.
-- Redundant with data/dishes.json on purpose: this file is the catalogue's
-- insurance policy if the app is ever rebuilt on a relational backend.

CREATE TABLE IF NOT EXISTS dishes (
  name text PRIMARY KEY, cuisine text NOT NULL, blurb text NOT NULL,
  seafood text NOT NULL, seafood_note text, ask_for text,
  condiment text NOT NULL, condiment_note text, takeaway text NOT NULL,
  price_band smallint NOT NULL, venues text[] NOT NULL, tags text[] NOT NULL
);

ON CONFLICT (name) DO NOTHING;
